  function updateRotationZ(event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);if(Number.isFinite(value))setRotationZ(value);}
  async function importPart(){error='';const path=await open({multiple:false,directory:false,filters:[{name:'CAD',extensions:['step','stp','dxf']}]});if(!path||Array.isArray(path))return;try{const summary=await invoke<ImportSummary>('inspect_import',{path});importSummary=summary;sourcePath=path;stockMode='manual';placement={...defaultPartPlacement};orientation={...defaultPartOrientation};wcs={...defaultWcs};resetOperations()}catch(e){error=String(e)}}
  async function saveCamProject(){error='';if(!importSummary||!sourcePath){error='Projekt kann erst gespeichert werden, wenn eine CAD-Quelldatei geladen ist.';return;}try{const path=await save({filters:[{name:'BeBlog CAM Projekt',extensions:['beblogcam']}],defaultPath:`${importSummary.fileName.replace(/\.[^.]+$/,'')}.beblogcam`});if(!path)return;const project=createCamProjectV1({sourcePath,sourceFileName:importSummary.fileName,stock,stockMode,placement,orientation,wcs,fixtures,machineEnvelopeEnabled,machineEnvelope,machineWcsOrigin,spindleHeadEnabled,spindleHead,operationsProject});await invoke('save_project_file',{path,content:serializeCamProject(project)});}catch(e){error=String(e)}}
  async function loadCamProject(){error='';const path=await open({multiple:false,directory:false,filters:[{name:'BeBlog CAM Projekt',extensions:['beblogcam']}]});if(!path||Array.isArray(path))return;try{const text=await invoke<string>('load_project_file',{path});const project=parseCamProject(text);const restoredSummary=await invoke<ImportSummary>('inspect_import',{path:project.source.path});importSummary=restoredSummary;sourcePath=project.source.path;stock={...project.setup.stock};stockMode=project.setup.stockMode;placement={...project.setup.placement};orientation={...project.setup.orientation};wcs={...project.setup.wcs};fixtures=project.setup.fixtures.map(fixture=>({...fixture}));machineEnvelopeEnabled=project.setup.machineEnvelopeEnabled;machineEnvelope={...project.setup.machineEnvelope};machineWcsOrigin={...project.setup.machineWcsOrigin};spindleHeadEnabled=project.setup.spindleHeadEnabled;spindleHead={...project.setup.spindleHead};operationsProject={operations:project.operationsProject.operations.map(cloneOperation),activeOperationId:project.operationsProject.activeOperationId};const restoredOperation=activeOperation(operationsProject)??operationsProject.operations[0]??defaultContourOperation;operation=cloneOperation(restoredOperation);toolTargetOperationId=operationsProject.activeOperationId??restoredOperation.id;activeStep='Bauteil';}catch(e){error=String(e)}}
</script>

<div class="app-shell">
<header class="topbar"><div><strong>BeBlog CAM</strong><span class="build">004W1</span></div><div class="project-name">{importSummary?.fileName??'Neues Projekt'}</div></header>
<aside class="rail" aria-label="Arbeitsablauf">{#each steps as step,i}<button class:active={activeStep===step} onclick={()=>goToStep(step)}><span>{String(i+1).padStart(2,'0')}</span>{step}</button>{/each}</aside>
<main class="workspace"><section class="viewport">
{#if importSummary}{#key `${importSummary.kind}:${stockMode}:${stock.width}:${stock.height}:${stock.thickness}:${placement.horizontal}:${placement.vertical}:${placement.offsetX}:${placement.offsetY}:${placement.offsetZ}:${orientation.rotationZDeg}:${wcs.x}:${wcs.y}:${wcs.z}`}<GeometryView summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} canonicalToolpath={activeStep==='Bearbeiten'?activeCanonicalToolpath:null} preflightCanonicalToolpaths={activeStep==='Prüfen'?preflightDxfToolpaths:[]} preflightStepToolpaths={activeStep==='Prüfen'?preflightStepToolpaths:(activeStep==='Bearbeiten'&&importSummary.kind==='step'&&activeCanonicalToolpath?[activeCanonicalToolpath]:[])} preflightFaceTargetToolpaths={activeStep==='Prüfen'?preflightFaceTargetStates.flatMap(entry=>entry.state.toolpath?[entry.state.toolpath]:[]):[]} selectedDrillCurveIds={operation.kind==='drill'?operation.curveIds:[]} onDrillViewModeChange={(mode)=>drillNativeViewMode=mode} roughingOperation={activeStep==='Bearbeiten'&&operation.kind==='z-level-roughing'?operation:null} surfaceFinishingOperation={activeStep==='Bearbeiten'&&operation.kind==='surface-finishing'?operation:null} stepSelectionOperation={activeStep==='Bearbeiten'&&importSummary.kind==='step'&&(operation.kind==='contour'||operation.kind==='pocket'||operation.kind==='drill')?operation:null} onStepContourChange={(patch)=>operation.kind==='contour'&&updateContour(patch)} onStepFaceIdChange={(faceId)=>operation.kind==='pocket'&&updatePocket({stepFaceId:faceId})} onStepHoleFeatureIdsChange={(featureIds)=>operation.kind==='drill'&&updateDrill({stepHoleFeatureIds:featureIds})} selectedFaceIds={activeStep==='Bearbeiten'&&((operation.kind==='z-level-roughing'&&zLevelMode(operation)==='face-target')||operation.kind==='surface-finishing')?operation.faceIds:[]} onSelectedFaceIdsChange={operation.kind==='surface-finishing'?updateSurfaceFinishingFaceIds:updateZLevelFaceIds} onFaceTargetChange={receiveFaceTargetState}/>{/key}{#if activeStep==='Bearbeiten'&&importSummary.kind==='dxf'&&operation.kind!=='facing'&&operation.kind!=='surface-finishing'&&!(operation.kind==='drill'&&drillNativeViewMode==='25d')}<ContourOverlay summary={importSummary} {stock} {stockMode} {placement} {orientation} {operation} onSelectContour={selectContour} onSelectCarveCurve={toggleCarveCurve} onSelectDrillCurve={toggleDrillCurve}/>{/if}<div class="view-label">Aufspannebene → {stockMode==='none'?'Bauteil':'Rohling → Bauteil'} → WCS</div>{:else}<div class="empty-state"><div class="mark">B</div><h1>Ein Bauteil öffnen</h1><p>STEP für exakte 3D-BRep-Geometrie oder DXF für planare Konturen.</p><button class="primary" onclick={importPart}>Bauteil öffnen</button></div>{/if}
</section><aside class="inspector">
{#if activeStep==='Bauteil'}<p class="eyebrow">01 · Bauteil</p><h2>Geometrie</h2>{#if importSummary}<dl><div><dt>Datei</dt><dd>{importSummary.fileName}</dd></div><div><dt>Format</dt><dd>{importSummary.kind.toUpperCase()}</dd></div><div><dt>Backend</dt><dd>{importSummary.backend}</dd></div><div><dt>Status</dt><dd>{importSummary.status==='ready'?'Bereit':'Native STEP-Anbindung fehlt in diesem Build'}</dd></div></dl><div class="placement-section"><p class="placement-title">Modellorientierung</p><div class="placement-grid"><button class:active={orientation.rotationZDeg===0} onclick={()=>setRotationZ(0)}>0°</button><button class:active={orientation.rotationZDeg===90} onclick={()=>setRotationZ(90)}>90°</button><button class:active={orientation.rotationZDeg===180} onclick={()=>setRotationZ(180)}>180°</button></div><div class="placement-grid two"><button class:active={orientation.rotationZDeg===270} onclick={()=>setRotationZ(270)}>270°</button><button onclick={()=>setRotationZ(0)}>Zurücksetzen</button></div><label>Rotation Z <input type="number" step="1" value={orientation.rotationZDeg} oninput={updateRotationZ}/> °</label><p class="note">Das dreht das Bauteil wirklich relativ zur Aufspannung. Die freie Mausrotation verändert nur die Kamera.</p></div>{#if Object.keys(importSummary.entities).length}<div class="entity-list">{#each Object.entries(importSummary.entities) as [name,count]}<span>{name} <b>{count}</b></span>{/each}</div>{/if}{#if importSummary.note}<p class="note">{importSummary.note}</p>{/if}<div class="placement-grid two"><button class="secondary" onclick={loadCamProject}>Projekt öffnen</button><button class="secondary" onclick={saveCamProject}>Projekt speichern</button></div><button class="secondary" onclick={importPart}>Anderes Bauteil öffnen</button>{:else}<p>Das CAD-Modell ist die Quelle für alle späteren Bearbeitungen.</p><div class="project-open-actions"><button class="primary" onclick={importPart}>Bauteil öffnen</button><button class="secondary" onclick={loadCamProject}>Projekt öffnen</button></div>{/if}
{:else if activeStep==='Rohling'}<p class="eyebrow">02 · Rohling</p><h2>Rohling</h2><div class="placement-section"><p class="placement-title">Rohling entsteht aus</p><div class="placement-grid"><button class:active={stockMode==='manual'} onclick={()=>setStockMode('manual')}>Maßen</button><button class:active={stockMode==='part-bounds'} onclick={()=>setStockMode('part-bounds')}>Bauteil</button>{#if importSummary?.kind==='dxf'}<button class:active={stockMode==='none'} onclick={()=>setStockMode('none')}>Kein Rohling</button>{/if}</div>{#if stockMode==='manual'}<label>Breite X <input type="number" min="0.1" step="1" value={stock.width} oninput={e=>updateStock('width',e)}/> mm</label><label>Tiefe Y <input type="number" min="0.1" step="1" value={stock.height} oninput={e=>updateStock('height',e)}/> mm</label><label>Dicke Z <input type="number" min="0.1" step="1" value={stock.thickness} oninput={e=>updateStock('thickness',e)}/> mm</label>{:else if stockMode==='part-bounds'}<p class="note">Der Rohling wird exakt aus der aktuellen Bauteil-Ausrichtung abgeleitet.{importSummary?.kind==='dxf'?' Die Materialdicke bleibt manuell.':''}</p>{#if importSummary?.kind==='dxf'}<label>Dicke Z <input type="number" min="0.1" step="1" value={stock.thickness} oninput={e=>updateStock('thickness',e)}/> mm</label>{/if}{:else}<p class="note">DXF kann auch ohne Rohling verwendet werden. Dann gibt es keine Rohlingdarstellung und keine stock-basierte Platzierung.</p>{/if}</div>{#if stockMode!=='none'}<div class="placement-section"><p class="placement-title">Bauteil im Rohling</p><div class="placement-grid"><button class:active={placement.horizontal==='left'} onclick={()=>placement={...placement,horizontal:'left'}}>Links</button><button class:active={placement.horizontal==='center'} onclick={()=>placement={...placement,horizontal:'center'}}>Mitte</button><button class:active={placement.horizontal==='right'} onclick={()=>placement={...placement,horizontal:'right'}}>Rechts</button></div><div class="placement-grid"><button class:active={placement.vertical==='front'} onclick={()=>placement={...placement,vertical:'front'}}>Unten</button><button class:active={placement.vertical==='center'} onclick={()=>placement={...placement,vertical:'center'}}>Mitte</button><button class:active={placement.vertical==='back'} onclick={()=>placement={...placement,vertical:'back'}}>Oben</button></div><label>Versatz X <input type="number" step="0.1" value={placement.offsetX} oninput={e=>updatePlacementOffset('offsetX',e)}/> mm</label><label>Versatz Y <input type="number" step="0.1" value={placement.offsetY} oninput={e=>updatePlacementOffset('offsetY',e)}/> mm</label><label>Versatz Z <input type="number" step="0.1" value={placement.offsetZ} oninput={e=>updatePlacementOffset('offsetZ',e)}/> mm</label></div>{/if}<div class="placement-section"><p class="placement-title">WCS / Werkstücknullpunkt</p><div class="placement-grid"><button class:active={wcs.x==='left'} onclick={()=>wcs={...wcs,x:'left'}}>X links</button><button class:active={wcs.x==='center'} onclick={()=>wcs={...wcs,x:'center'}}>X Mitte</button><button class:active={wcs.x==='right'} onclick={()=>wcs={...wcs,x:'right'}}>X rechts</button></div><div class="placement-grid"><button class:active={wcs.y==='front'} onclick={()=>wcs={...wcs,y:'front'}}>Y unten</button><button class:active={wcs.y==='center'} onclick={()=>wcs={...wcs,y:'center'}}>Y Mitte</button><button class:active={wcs.y==='back'} onclick={()=>wcs={...wcs,y:'back'}}>Y oben</button></div><div class="placement-grid two"><button class:active={wcs.z==='top'} onclick={()=>wcs={...wcs,z:'top'}}>Z oben</button><button class:active={wcs.z==='bottom'} onclick={()=>wcs={...wcs,z:'bottom'}}>Z unten</button></div></div><FixtureSetupPanel {fixtures} onChange={next=>fixtures=next}/><MachineSetupPanel enabled={machineEnvelopeEnabled} envelope={machineEnvelope} origin={machineWcsOrigin} onChange={next=>{machineEnvelopeEnabled=next.enabled;machineEnvelope=next.envelope;machineWcsOrigin=next.origin}}/><SpindleHeadSetupPanel enabled={spindleHeadEnabled} head={spindleHead} onChange={next=>{spindleHeadEnabled=next.enabled;spindleHead=next.head}}/>
{:else if activeStep==='Werkzeuge'}{#if importSummary}<div class="tool-shell"><FeedsSpeedsCalculator selectedToolId={toolTargetOperation?.tool.id??null} selectedToolKind={toolTargetOperation?.tool.kind??null} selectedToolName={toolTargetOperation?.tool.name??null} selectedToolDiameterMm={toolTargetOperation?.tool.diameterMm??null} selectedToolCuttingLengthMm={toolTargetOperation?.tool.cuttingLengthMm??null} selectedToolStickoutMm={toolTargetOperation?.tool.stickoutMm??null} selectedToolShaftDiameterMm={toolTargetOperation?.tool.shaftDiameterMm??null} selectedToolHolderDiameterMm={toolTargetOperation?.tool.holderDiameterMm??null} operationId={toolTargetOperation?.id??null} operationLabel={toolTargetOperation?`${operationLabel(toolTargetOperation.kind)} · ${toolTargetOperation.name}`:null} onOperationSelect={setToolTargetOperation} operationChoices={operationsProject.operations.map(op=>({id:op.id,label:`${operationLabel(op.kind)} · ${op.name}`,name:op.name,summary:operationSummary(op)}))} onTransfer={applyToolOperationTransfer}/></div>{:else}<p class="eyebrow">03 · Werkzeuge</p><h2>Werkzeuge</h2><p>Noch kein Bauteil geladen.</p>{/if}
{:else if activeStep==='Bearbeiten'}<p class="eyebrow">04 · Bearbeiten</p><h2>Bearbeitung</h2>{#if importSummary}<div class="placement-section"><p class="placement-title">Bearbeitungen im Job</p><div class="operation-list">{#each operationsProject.operations as op,index}<div class="operation-row" class:current-operation={op.id===operation.id}><button class="operation-select" onclick={()=>activateOperation(op.id)}><span class="operation-index">{String(index+1).padStart(2,'0')}</span><span><strong>{op.name}</strong><small>{operationSummary(op)}</small></span></button>{#if operationsProject.operations.length>1}<button class="operation-delete" aria-label={`${op.name} löschen`} onclick={()=>deleteOperation(op.id)}>×</button>{/if}</div>{/each}</div><div class="operation-add"><span>Hinzufügen</span><button onclick={()=>appendOperation('facing')}>Planen</button><button onclick={()=>appendOperation('contour')}>Kontur</button><button onclick={()=>appendOperation('pocket')}>Tasche</button><button onclick={()=>appendOperation('carve')}>Carve</button><button onclick={()=>appendOperation('drill')}>Bohren</button><button onclick={()=>appendOperation('z-level-roughing')}>Z-Level</button><button onclick={()=>appendOperation('surface-finishing')}>3D Schlichten</button></div></div>
<div class="placement-section"><p class="placement-title">Aktive Bearbeitung</p><div class="placement-grid two"><button class:active={operation.kind==='facing'} onclick={()=>setOperationKind('facing')}>Planen</button><button class:active={operation.kind==='contour'} onclick={()=>setOperationKind('contour')}>Kontur</button></div><div class="placement-grid two"><button class:active={operation.kind==='pocket'} onclick={()=>setOperationKind('pocket')}>Tasche</button><button class:active={operation.kind==='carve'} onclick={()=>setOperationKind('carve')}>Carve</button></div><div class="placement-grid two"><button class:active={operation.kind==='drill'} onclick={()=>setOperationKind('drill')}>Bohren</button><button class:active={operation.kind==='z-level-roughing'} onclick={()=>setOperationKind('z-level-roughing')}>Z-Level Schruppen</button></div><div class="placement-grid two"><button class:active={operation.kind==='surface-finishing'} onclick={()=>setOperationKind('surface-finishing')}>3D Schlichten</button></div></div>
{#if operation.kind==='facing'}<p>Die komplette rechteckige Rohlingoberseite wird geplant. Es ist keine Geometrieauswahl erforderlich.</p><p class="note"><strong>Ziel:</strong> {stock.width.toFixed(3)} × {stock.height.toFixed(3)} mm Rohlingfläche · Z-Null auf Oberseite erforderlich.</p>
{:else if operation.kind==='carve'}<p>{importSummary.kind==='dxf'?'Wähle offene DXF-Geometrien einzeln oder gemeinsam über ihre Ebene.':'Carve aus STEP folgt später.'}</p>{#if importSummary.kind==='dxf'}<div class="placement-section"><p class="placement-title">Geometrie auswählen</p><div class="placement-grid two"><button class:active={operation.selectionMode==='individual'} onclick={()=>setCarveSelectionMode('individual')}>Einzeln</button><button class:active={operation.selectionMode==='layer'} onclick={()=>setCarveSelectionMode('layer')}>Ebene</button></div>{#if operation.selectionMode==='layer'}<label>Ebene <select value={operation.layerName??''} onchange={chooseCarveLayer}><option value="">Ebene wählen …</option>{#each carveLayerNames() as layer}<option value={layer}>{layer}</option>{/each}</select></label>{/if}<p class="note"><strong>Auswahl:</strong> {operation.curveIds.length}{operation.layerName?` von ${carveLayerEligibleCount(operation.layerName)}`:''} offene Geometrie{operation.curveIds.length===1?'':'n'}{operation.layerName?` · Ebene ${operation.layerName}`:''}.</p>{#if operation.selectionMode==='layer'&&operation.layerName}<p class="note">Die Ebene ist die Vorauswahl. Klicke markierte Geometrien im Viewport an, um einzelne Elemente auszuschließen; erneuter Klick fügt sie wieder hinzu.</p>{/if}</div>{/if}
{:else if operation.kind==='drill'}<p>{importSummary.kind==='dxf'?'Wähle native DXF-Kreise als Bohrungen. Der Kreis definiert Mittelpunkt und Soll-Durchmesser; danach wählst du das Herstellungsverfahren.':'Klicke die sicher erkannten zylindrischen Bohrungsflächen im STEP-Viewport an. Nur explizit markierte Bohrungen werden bearbeitet.'}</p>{#if importSummary.kind==='step'}<p class="note"><strong>STEP-Auswahl:</strong> {operation.stepHoleFeatureIds?.length??0} Bohrung{(operation.stepHoleFeatureIds?.length??0)===1?'':'en'} explizit gewählt.</p>{/if}{#if importSummary.kind==='dxf'}<div class="placement-section"><p class="placement-title">Bohrungen auswählen</p><div class="placement-grid two"><button class:active={operation.selectionMode==='individual'} onclick={()=>setDrillSelectionMode('individual')}>Einzeln</button><button class:active={operation.selectionMode==='layer'} onclick={()=>setDrillSelectionMode('layer')}>Ebene</button></div>{#if operation.selectionMode==='layer'}<label>Ebene <select value={operation.layerName??''} onchange={chooseDrillLayer}><option value="">Ebene wählen …</option>{#each drillLayerNames() as layer}<option value={layer}>{layer}</option>{/each}</select></label>{/if}<p class="note"><strong>Auswahl:</strong> {operation.curveIds.length}{operation.layerName?` von ${drillLayerEligibleCount(operation.layerName)}`:''} Bohrung{operation.curveIds.length===1?'':'en'}{operation.layerName?` · Ebene ${operation.layerName}`:''}.</p>{#if operation.selectionMode==='layer'&&operation.layerName}<p class="note">Die Ebene ist nur die Vorauswahl. Einzelne Kreise lassen sich im Viewport wieder entfernen oder hinzufügen.</p>{/if}</div>{/if}<div class="placement-section"><p class="placement-title">Herstellungsverfahren</p><div class="placement-grid two"><button class:active={operation.method==='drill'} onclick={()=>updateDrill({method:'drill'})}>Axial bohren</button><button class:active={operation.method==='helical-mill'} onclick={()=>updateDrill({method:'helical-mill'})}>Helixfräsen</button></div><p class="note">Axial bohren verlangt einen Bohrer passend zum Soll-Ø. Helixfräsen verwendet einen kleineren Fräser und erzeugt die Bohrung über die Fräsermittelbahn.</p></div><div class="placement-section"><p class="placement-title">Bohrtiefe</p><div class="placement-grid two"><button class:active={(operation.depthMode??'manual')==='manual'} onclick={()=>updateDrill({depthMode:'manual'})}>Manuell</button><button class:active={(operation.depthMode??'manual')==='stock-bottom'} onclick={()=>updateDrill({depthMode:'stock-bottom'})}>Durch Rohling</button></div>{#if (operation.depthMode??'manual')==='stock-bottom'}<label>Overcut unter Rohling <input type="number" min="0" step="0.1" value={operation.overcutMm??0} oninput={updateDrillOvercut}/> mm</label>{#if stockMode==='none'}<p class="note"><strong>Durchbohren nicht möglich:</strong> Dafür muss ein Rohling definiert sein.</p>{:else}<p class="note"><strong>Ziel:</strong> Rohling {stock.thickness.toFixed(3)} mm + {Number(operation.overcutMm??0).toFixed(3)} mm Overcut → End-Z <strong>{(-(stock.thickness+Number(operation.overcutMm??0))).toFixed(3)} mm</strong>.</p>{/if}{:else}<p class="note">Manuell verwendet die eingestellte Gesamttiefe. Bei STEP bleibt die erkannte Bohrungsgeometrie die Sicherheitsgrenze; für bewusstes Durchbohren „Durch Rohling“ wählen.</p>{/if}</div>
{:else if operation.kind==='contour'||operation.kind==='pocket'}<p>{importSummary.kind==='dxf'?'Klicke im Viewport auf eine geschlossene Kontur.':operation.kind==='contour'?'Offene Kontur: Klicke die Seitenfläche(n), deren obere Profilkante gefräst werden soll. Geschlossene Kontur: Wähle weiterhin eine eindeutige Randkante.':'Klicke die planare STEP-Face, die als Taschenboden bearbeitet werden soll.'}</p>{#if importSummary.kind==='dxf'}<p class="note"><strong>Ziel:</strong> {operation.contourId===null?'Noch keine geschlossene Kontur gewählt.':`Kontur ${operation.contourId+1} gewählt.`}</p>{:else if operation.kind==='contour'}<p class="note"><strong>STEP-Ziel:</strong> {operation.topology==='open'?(operation.stepContourFaceIds?.length?`${operation.stepContourFaceIds.length} Seitenfläche${operation.stepContourFaceIds.length===1?'':'n'} gewählt.`:'Noch keine Seitenfläche gewählt.'):(operation.stepWireId==null?'Noch keine geschlossene Kontur gewählt.':`Wire ${operation.stepWireId} gewählt.`)}</p>{:else}<p class="note"><strong>STEP-Ziel:</strong> {operation.stepFaceId==null?'Noch keine Taschen-Face explizit gewählt.':`Face ${operation.stepFaceId} gewählt.`}</p>{/if}{/if}
<div class="placement-section"><p class="placement-title">Werkzeug</p><label>Durchmesser <input type="number" min="0.1" step="0.1" value={operation.tool.diameterMm} oninput={updateToolDiameter}/> mm</label>{#if operation.tool.kind}<p class="note">Werkzeugtyp aus Bibliothek: <strong>{operation.tool.kind==='face-mill'?'Planfräser':operation.tool.kind==='end-mill'?'Schaftfräser':operation.tool.kind==='ball-nose'?'Vollradiusfräser':'V-Fräser'}</strong>.</p>{/if}</div>
{#if operation.kind==='facing'}<div class="placement-section"><p class="placement-title">Planstrategie</p><div class="placement-grid two"><button class:active={operation.direction==='x'} onclick={()=>updateFacing({direction:'x'})}>Bahnen in X</button><button class:active={operation.direction==='y'} onclick={()=>updateFacing({direction:'y'})}>Bahnen in Y</button></div><label>Seitliche Zustellung <input type="number" min="5" max="90" step="5" value={operation.stepoverPercent} oninput={updateFacingStepover}/> % Werkzeugdurchmesser</label><p class="note">Zickzack ohne Rapid-Bewegung im Material. Die Stirnkanten werden um einen Werkzeugradius überfahren, damit die gesamte Rohlingfläche abgedeckt wird.</p></div>
{:else if operation.kind==='contour'}<div class="placement-section"><p class="placement-title">Konturtyp</p><div class="placement-grid two"><button class:active={operation.topology==='closed'} onclick={()=>updateContour({topology:'closed',excludedSegmentIds:[]})}>Geschlossen</button><button class:active={operation.topology==='open'} onclick={()=>updateContour({topology:'open'})}>Offen</button></div>{#if importSummary.kind==='step'&&operation.topology==='open'}<p class="note">Klicke Seitenflächen direkt im STEP-Modell an. Angrenzende Flächen erweitern die offene Profilkante; ein erneuter Klick entfernt sie. Die hervorgehobenen Profilkanten können anschließend mit großzügiger Trefferfläche fein angepasst werden.</p>{/if}</div><div class="placement-section"><p class="placement-title">Bahn</p>{#if operation.topology==='open'}<div class="placement-grid"><button class:active={operation.openSide==='left'} onclick={()=>updateContour({openSide:'left'})}>Links</button><button class:active={operation.openSide==='right'} onclick={()=>updateContour({openSide:'right'})}>Rechts</button><button class:active={operation.openSide==='on-line'} onclick={()=>updateContour({openSide:'on-line'})}>Auf Linie</button></div>{:else}<div class="placement-grid"><button class:active={operation.side==='outside'} onclick={()=>updateContour({side:'outside'})}>Außen</button><button class:active={operation.side==='inside'} onclick={()=>updateContour({side:'inside'})}>Innen</button><button class:active={operation.side==='on-line'} onclick={()=>updateContour({side:'on-line'})}>Auf Linie</button></div>{/if}<div class="placement-grid two"><button class:active={operation.direction==='climb'} onclick={()=>updateContour({direction:'climb'})}>Gleichlauf</button><button class:active={operation.direction==='conventional'} onclick={()=>updateContour({direction:'conventional'})}>Gegenlauf</button></div></div>
<div class="placement-section"><p class="placement-title">Schnitttiefe</p><div class="placement-grid two"><button class:active={(operation.depthMode??'manual')==='manual'} onclick={()=>updateContour({depthMode:'manual'})}>Manuell</button><button class:active={(operation.depthMode??'manual')==='stock-bottom'} onclick={()=>updateContour({depthMode:'stock-bottom'})}>Durchfräsen</button></div>{#if (operation.depthMode??'manual')==='stock-bottom'}<label>Overcut <input type="number" min="0" step="0.1" value={operation.overcutMm??0} oninput={updateContourOvercut}/> mm</label>{#if contourDepthState?.ok}<p class="note"><strong>Ziel:</strong> Rohling {stock.thickness.toFixed(3)} mm + {Number(operation.overcutMm??0).toFixed(3)} mm Overcut → End-Z <strong>{(-contourDepthState.depthMm).toFixed(3)} mm</strong>.</p>{:else}<p class="note"><strong>Durchfräsen nicht freigegeben:</strong> {contourDepthState?.errors.join(' ')}</p>{/if}{:else}<p class="note">Manuelle Konturtiefe verwendet die unten eingestellte Gesamttiefe.</p>{/if}</div><div class="placement-section"><p class="placement-title">Haltestege</p><div class="placement-grid two"><button class:active={!(operation.tabsEnabled??false)} onclick={()=>updateContour({tabsEnabled:false})}>Aus</button><button class:active={operation.tabsEnabled??false} onclick={()=>updateContour({tabsEnabled:true})}>Aktiv</button></div>{#if operation.tabsEnabled??false}<label>Anzahl <input type="number" min="1" step="1" value={operation.tabCount??4} oninput={updateContourTabCount}/></label><label>Breite <input type="number" min="0.1" step="0.5" value={operation.tabWidthMm??6} oninput={updateContourTabWidth}/> mm</label><label>Resthöhe <input type="number" min="0.1" step="0.1" value={operation.tabHeightMm??1.5} oninput={updateContourTabHeight}/> mm</label><p class="note">Haltestege werden gleichmäßig entlang geschlossener Konturen verteilt und nur in den tiefen Zustellungen stehen gelassen.</p>{/if}</div><div class="placement-section"><p class="placement-title">Aufmaß & Schlichten</p><label>Radiales Aufmaß <input type="number" min="0" step="0.05" value={operation.radialAllowanceMm??0} oninput={updateContourRadialAllowance}/> mm</label><label>Axiales Aufmaß <input type="number" min="0" step="0.05" value={operation.axialAllowanceMm??0} oninput={updateContourAxialAllowance}/> mm</label><div class="placement-grid two"><button class:active={!(operation.finishPassEnabled??false)} onclick={()=>updateContour({finishPassEnabled:false})}>Nur Schruppen</button><button class:active={operation.finishPassEnabled??false} onclick={()=>updateContour({finishPassEnabled:true})}>Schlichten</button></div>{#if operation.finishPassEnabled??false}<label>Schlichtdurchgänge <input type="number" min="1" step="1" value={operation.finishPassCount??1} oninput={updateContourFinishPassCount}/></label><p class="note">Der Schruppgang lässt radial und axial das definierte Aufmaß stehen. Danach fährt der Schlichtdurchgang die nominale Kontur auf Sollmaß; weitere Durchgänge dienen als Wiederhol-/Spring-Pass.</p>{:else if (operation.radialAllowanceMm??0)>0||(operation.axialAllowanceMm??0)>0}<p class="note"><strong>Aufmaß bleibt stehen:</strong> Ohne Schlichtdurchgang wird das definierte Material bewusst nicht auf Sollmaß entfernt.</p>{:else}<p class="note">Kein Aufmaß und kein separater Schlichtdurchgang aktiv.</p>{/if}</div>{#if importSummary.kind==='step'&&operation.topology==='open'}<div class="placement-section"><p class="placement-title">Einfahrt</p><div class="placement-grid two"><button class:active={(operation.leadMode??'none')==='none'} onclick={()=>updateContour({leadMode:'none'})}>Aus</button><button class:active={(operation.leadMode??'none')==='line'} onclick={()=>updateContour({leadMode:'line'})}>Rampe</button></div>{#if (operation.leadMode??'none')==='line'}<label>Rampenlänge <input type="number" min="0.1" step="0.5" value={operation.leadInLengthMm??3} oninput={updateContourLeadInLength}/> mm</label><p class="note">Die Rampe bleibt vollständig auf der korrigierten Nutbahn. Sie senkt von der vorherigen Z-Ebene entlang der Kontur auf die neue Zustelltiefe ab, bereinigt den Rampenabschnitt auf Soll-Z zurück zum Start und fährt danach die komplette offene Kontur. Am Ende folgt der normale Retract auf Sicherheits-Z.</p>{/if}</div>{:else}<div class="placement-section"><p class="placement-title">Ein-/Ausfahrt</p><div class="placement-grid two"><button class:active={(operation.leadMode??'none')==='none'} onclick={()=>updateContour({leadMode:'none'})}>Aus</button><button class:active={(operation.leadMode??'none')==='line'} onclick={()=>updateContour({leadMode:'line'})}>Tangential</button></div>{#if (operation.leadMode??'none')==='line'}<label>Einfahrt <input type="number" min="0.1" step="0.5" value={operation.leadInLengthMm??3} oninput={updateContourLeadInLength}/> mm</label><label>Ausfahrt <input type="number" min="0.1" step="0.5" value={operation.leadOutLengthMm??3} oninput={updateContourLeadOutLength}/> mm</label><p class="note">Der Fräser fährt linear tangential in die geschlossene Kontur ein und nach dem letzten Schnitt tangential wieder aus. Haltestege werden davor aufgelöst; die Ein-/Ausfahrt wird daher nicht an jedem Haltesteg wiederholt.</p>{/if}</div>{/if}
{:else if operation.kind==='pocket'}<div class="placement-section"><p class="placement-title">Räumstrategie</p><div class="placement-grid two"><button class:active={operation.strategy==='auto'} onclick={()=>updatePocket({strategy:'auto'})}>Automatisch</button><button class:active={operation.strategy==='raster'} onclick={()=>updatePocket({strategy:'raster'})}>Raster</button></div><div class="placement-grid two"><button class:active={operation.strategy==='concentric'} onclick={()=>updatePocket({strategy:'concentric'})}>Kreis</button><button class:active={operation.strategy==='parallel'} onclick={()=>updatePocket({strategy:'parallel'})}>Konturparallel</button></div><p class="note">Automatisch wählt für DXF weiterhin die passende 2D-Strategie; bei STEP wird eine insellose BRep-Tasche konzentrisch und eine Region mit Inseln konturparallel bearbeitet.</p></div><div class="placement-section"><p class="placement-title">Stock-aware Roughing</p><div class="placement-grid two"><button class:active={!(operation.stockAwareRoughingEnabled??false)} onclick={()=>setPocketStockAwareRoughing(false)}>Aus</button><button class:active={operation.stockAwareRoughingEnabled??false} onclick={()=>setPocketStockAwareRoughing(true)}>Aktiv</button></div>{#if operation.stockAwareRoughingEnabled??false}<label>Max. radialer Eingriff <input type="number" min="1" max="100" step="1" value={operation.maxRadialEngagementPercent??35} oninput={updatePocketMaxRadialEngagement}/><span>%</span></label><p class="note">Adaptive Clearing v1: Bereits geräumte Werkzeugkorridore werden pro Z-Ebene berücksichtigt. Überschreitet eine Folge-Bahn den erlaubten radialen Eingriff, sperrt der Preflight die Bearbeitung.</p>{/if}</div><div class="placement-section"><p class="placement-title">Restmaterial</p><div class="placement-grid two"><button class:active={!(operation.restMachiningEnabled??false)} onclick={()=>setPocketRestMachining(false)}>Aus</button><button class:active={operation.restMachiningEnabled??false} onclick={()=>setPocketRestMachining(true)}>Aktiv</button></div>{#if operation.restMachiningEnabled??false}<label>Vorherige Tasche <select value={operation.restFromOperationId??''} onchange={choosePocketRestSource}><option value="">Quelle wählen …</option>{#each restSourcePocketOperations() as source}<option value={source.id}>{source.name} · Ø {source.tool.diameterMm.toFixed(3)} mm</option>{/each}</select></label>{#if restSourcePocketOperations().length===0}<p class="note"><strong>Keine geeignete Quelle:</strong> Zuerst muss eine frühere aktive Tasche mit demselben Ziel und größerem Werkzeug existieren.</p>{:else}<p class="note">Nur tatsächlich verbliebene Restsegmente werden mit dem kleineren Werkzeug nachgeräumt. Quelle und Folgeoperation müssen dasselbe Taschenziel verwenden.</p>{/if}{/if}</div><div class="placement-section"><p class="placement-title">Ausräumen</p><label>Seitliche Zustellung <input type="number" min="5" max="90" step="5" value={operation.stepoverPercent} oninput={updatePocketStepover}/> % Werkzeugdurchmesser</label><label>Eintauchen <select value={operation.entry} onchange={updatePocketEntry}><option value="plunge">Senkrecht</option><option value="ramp">Rampe</option><option value="helix">Helix</option></select></label>{#if operation.entry==='ramp'}<label>Rampenwinkel <input type="number" min="0.1" max="15" step="0.5" value={operation.rampAngleDeg} oninput={e=>updateNumber('rampAngleDeg',e)}/> °</label><p class="note">Die Rampe nutzt die verfügbare Taschenbahn kumulativ und steigt über mehrere Segmente bis zur aktuellen Z-Ebene ab.</p>{/if}</div><div class="placement-section"><p class="placement-title">Aufmaß & Schlichten</p><label>Radiales Aufmaß <input type="number" min="0" step="0.05" value={operation.radialAllowanceMm??0} oninput={updatePocketRadialAllowance}/> mm</label><label>Axiales Aufmaß <input type="number" min="0" step="0.05" value={operation.axialAllowanceMm??0} oninput={updatePocketAxialAllowance}/> mm</label><div class="placement-grid two"><button class:active={!(operation.finishPassEnabled??false)} onclick={()=>updatePocket({finishPassEnabled:false})}>Nur Schruppen</button><button class:active={operation.finishPassEnabled??false} onclick={()=>updatePocket({finishPassEnabled:true})}>Schlichten</button></div>{#if operation.finishPassEnabled??false}<label>Schlichtdurchgänge <input type="number" min="1" step="1" value={operation.finishPassCount??1} oninput={updatePocketFinishPassCount}/></label><p class="note">Schruppen lässt das definierte radiale und axiale Aufmaß stehen. Danach folgt die finale Kontur und Bodenebene auf Sollmaß; weitere Durchgänge wiederholen diese Geometrie als Spring-Pass.</p>{:else if (operation.radialAllowanceMm??0)>0||(operation.axialAllowanceMm??0)>0}<p class="note"><strong>Aufmaß bleibt stehen:</strong> Ohne Schlichtdurchgang wird das definierte Material bewusst nicht auf Sollmaß entfernt.</p>{:else}<p class="note">Kein Aufmaß und kein separater Schlichtdurchgang aktiv.</p>{/if}</div>{:else if operation.kind==='z-level-roughing'}<div class="placement-section"><p class="placement-title">Schruppziel</p><div class="placement-grid two"><button class:active={zLevelMode(operation)==='face-target'} onclick={()=>setZLevelRoughingMode('face-target')}>Ziel-Fläche</button><button class:active={zLevelMode(operation)==='model'} onclick={()=>setZLevelRoughingMode('model')}>Gesamtmodell</button></div>{#if zLevelMode(operation)==='face-target'}<p class="note">Wähle mindestens eine horizontale oder schräge STEP-Face als fachliches Schruppziel. Die ausgewählten Flächen bestimmen die Zielregion und Z-Tiefe.</p><p class="placement-title">Inneninseln</p><div class="placement-grid two"><button class:active={(operation.islandMode??'preserve')==='preserve'} onclick={()=>updateZLevelRoughing({islandMode:'preserve'})}>Stehen lassen</button><button class:active={(operation.islandMode??'preserve')==='clear'} onclick={()=>updateZLevelRoughing({islandMode:'clear'})}>Mit schruppen</button></div><p class="note">„Stehen lassen“ respektiert Bohrungen und innere Aussparungen als Inseln. „Mit schruppen“ füllt diese Innenkonturen für die Schruppregion und räumt das Material bis zur gewählten Zielfläche ab.</p>{#if operation.faceIds.length}<p class="note"><strong>Auswahl:</strong> {operation.faceIds.length} Face{operation.faceIds.length===1?'':'s'}.</p>{/if}{:else}<p class="note">Gesamtmodell-Schruppen verwendet den nativen BRep-Solid-Kernel. Der Fräser räumt nur Rohlingbereiche, die nicht vom Modellkörper belegt sind.</p>{/if}</div><div class="placement-section"><p class="placement-title">Schruppstrategie</p><label>Seitliche Zustellung <input type="number" min="1" max="100" step="1" value={operation.stepoverPercent} oninput={updateZLevelStepover}/> % Werkzeugdurchmesser</label><p class="note">Z-Level erzeugt pro Tiefenebene planare Schruppbahnen; bei Gesamtmodell aus dem BRep-Solid, bei Ziel-Fläche aus der ausgewählten Region.</p></div>{:else if operation.kind==='surface-finishing'}<div class="placement-section"><p class="placement-title">Schlichtstrategie</p><div class="placement-grid two"><button class:active={operation.direction==='x'} onclick={()=>updateSurfaceFinishing({direction:'x'})}>Parallel X</button><button class:active={operation.direction==='y'} onclick={()=>updateSurfaceFinishing({direction:'y'})}>Parallel Y</button></div><label>Seitliche Zustellung <input type="number" min="1" max="100" step="1" value={operation.stepoverPercent} oninput={updateSurfaceFinishingStepover}/> % Werkzeugdurchmesser</label><p class="note">3D Schlichten projiziert die Bahn direkt auf die ausgewählten BRep-Faces. Für v1 ist ausschließlich ein Vollradiusfräser freigegeben.</p></div>{/if}
<div class="placement-section"><p class="placement-title">Schnittdaten</p>{#if operation.kind!=='z-level-roughing'&&operation.kind!=='surface-finishing'&&!(operation.kind==='contour'&&(operation.depthMode??'manual')==='stock-bottom')&&!(operation.kind==='drill'&&(operation.depthMode??'manual')==='stock-bottom')}<label>{operation.kind==='facing'?'Planabtrag':'Gesamttiefe'} <input type="number" min="0.01" step="0.1" value={operation.totalDepthMm} oninput={e=>updateNumber('totalDepthMm',e)}/> mm</label>{/if}<label>{(operation.kind==='drill'&&operation.method==='helical-mill')||(operation.kind==='pocket'&&operation.entry==='helix')?'Helix-Zustellung / Umdrehung':'Zustellung'} <input type="number" min="0.01" step="0.1" value={operation.stepDownMm} oninput={e=>updateNumber('stepDownMm',e)}/> mm</label><label>Vorschub <input type="number" min="1" step="10" value={operation.feedMmMin} oninput={e=>updateNumber('feedMmMin',e)}/> mm/min</label><label>Eintauchen <input type="number" min="1" step="10" value={operation.plungeMmMin} oninput={e=>updateNumber('plungeMmMin',e)}/> mm/min</label><label>Drehzahl <input type="number" min="1" step="100" value={operation.spindleRpm} oninput={e=>updateNumber('spindleRpm',e)}/> 1/min</label><label>Sicherheits-Z <input type="number" min="0.1" step="0.5" value={operation.safeZMm} oninput={e=>updateNumber('safeZMm',e)}/> mm</label></div><p class="note"><strong>004W1:</strong> Bohren und Helixfräsen teilen denselben kanonischen Sicherheits- und NC-Pfad; Durchbohren verwendet Rohlingunterseite plus Overcut.</p>{:else}<p>Noch kein Bauteil geladen.</p>{/if}
{:else if activeStep==='Prüfen'}{#if importSummary}<p class="eyebrow">05 · Prüfen</p><h2>Job prüfen</h2>{#if jobPreflight}<JobPreflightPanel result={jobPreflight}/>{/if}{#if stockMode==='none'}<p class="note">Stock-Simulation ist ohne definierten Rohling nicht verfügbar.</p>{:else if wcs.z!=='top'}<p class="note">Stock-Simulation 004P ist aktuell nur mit Z-Null auf Rohlingoberseite verfügbar.</p>{:else}<div class="placement-section"><p class="placement-title">Reststock-Simulation</p><p class="note">Die 2.5D-Heightfield-Simulation wird im Job-Preflight aus allen akzeptierten kanonischen Werkzeugwegen in Bearbeitungsreihenfolge aufgebaut.</p><dl><div><dt>Status</dt><dd>Im Preflight aktiv</dd></div><div><dt>Basis</dt><dd>Rohling {stock.width.toFixed(1)} × {stock.height.toFixed(1)} × {stock.thickness.toFixed(1)} mm</dd></div><div><dt>Operationen</dt><dd>{operationsProject.operations.filter(op=>op.enabled!==false).length} aktiv</dd></div><div><dt>Modell</dt><dd>2.5D Heightfield · Werkzeugradius-Sweep</dd></div></dl></div>{/if}{:else}<p class="eyebrow">05 · Prüfen</p><h2>Preflight</h2><p>Noch kein Bauteil geladen.</p>{/if}
{:else if activeStep==='Fräsen'}{#if importSummary}{#if jobPreflight}<JobGCodePanel summary={importSummary} {stock} {stockMode} {placement} {orientation} {wcs} {fixtures} machineEnvelope={machineEnvelopeEnabled?machineEnvelope:null} machineWcsOrigin={machineEnvelopeEnabled?machineWcsOrigin:null} spindleHead={spindleHeadEnabled?spindleHead:null} operations={operationsProject.operations} preflight={jobPreflight}/>{/if}{:else}<p class="eyebrow">06 · Fräsen</p><h2>G-Code</h2><p>Noch kein Bauteil geladen.</p>{/if}
{:else}<p class="eyebrow">{String(steps.indexOf(activeStep)+1).padStart(2,'0')} · {activeStep}</p><h2>{activeStep}</h2><p>Dieser Schritt wird in den nächsten Builds freigeschaltet.</p>{/if}
</aside></main></div>

<style>
.operation-list{display:grid;gap:6px}.operation-row{display:grid;grid-template-columns:1fr auto;align-items:stretch;border:1px solid #deded8;border-radius:8px;background:#fafaf8;overflow:hidden}.operation-row.current-operation{border-color:#9aa49e;background:#f1f3ef}.operation-select{display:grid;grid-template-columns:28px 1fr;gap:8px;text-align:left;align-items:start;border:0;background:transparent;padding:9px 10px;cursor:pointer;color:#39413d}.operation-select span:last-child{display:grid;gap:2px}.operation-select strong{font-size:.8rem}.operation-select small{font-size:.7rem;color:#747a76;font-weight:400}.operation-index{font-size:.68rem;color:#8a8f8b;padding-top:2px}.operation-delete{border:0;border-left:1px solid #deded8;background:transparent;padding:0 10px;color:#8b5d58;cursor:pointer;font-size:1rem}.operation-add{display:grid;grid-template-columns:1fr repeat(5,auto);gap:5px;align-items:center;margin-top:8px}.operation-add span{font-size:.76rem;color:#696f6b}.operation-add button{border:1px solid #d5d7d2;border-radius:6px;background:#fff;padding:5px 7px;font-size:.7rem;color:#4e5651;cursor:pointer}
.project-open-actions{display:grid;gap:12px;margin-top:24px}.project-open-actions .primary,.project-open-actions .secondary{width:100%;min-height:46px;margin:0;padding:11px 14px;border-radius:9px;font-weight:500}.project-open-actions .primary{border-color:#27322c;background:#27322c;color:#fff}.project-open-actions .secondary{border-color:#d2d4cf;background:#fff;color:#28302c}
</style>